class stringx { char data_[8]; public: int size() const; };
class Random { unsigned int rand_next; public: unsigned int NextRand(); int rand(int end) { unsigned int r = NextRand(); return r % end; } int rand(int begin, int end) { unsigned int r = NextRand(); return r % (end-begin) + begin; } };
extern Random *g_random_ptr;
inline int random(int end) { int i = g_random_ptr->rand(end); return i; }
inline int random(int begin,int end) { int i = g_random_ptr->rand(begin, end); return i; }
template <class T> void adjustSizes(T &x, T &y);
void nglPrintf(const char *, ...);
void assert(int);
class StringList {
public:
  enum { MAX_STRING_SIZE = 150 };
  static int RANGE_D_SPEED_LO; static int RANGE_D_SPEED_HI; static int RANGE_F_SPEED_LO; static int RANGE_F_SPEED_HI; static int RANGE_D_MAX_LO; static int RANGE_D_MAX_HI;
  stringx data; float x; float y; float fall_speed[MAX_STRING_SIZE]; float drift_speed[MAX_STRING_SIZE]; int drift_max[MAX_STRING_SIZE]; float delta_x[MAX_STRING_SIZE]; float delta_y[MAX_STRING_SIZE];
  void MakeRand(void);
};
